import { z } from 'zod';

/** Entity ids are UUIDs generated by the client, so offline-created records keep their id. */
export const id = z.uuid();
export type Id = z.infer<typeof id>;

/** Calendar day in the user's local time zone, `YYYY-MM-DD`. */
export const isoDate = z.iso.date();
export type IsoDate = z.infer<typeof isoDate>;

/** Point in time, ISO 8601 with offset. */
export const timestamp = z.iso.datetime({ offset: true });

/** Error body returned by every failing API call. */
export const apiError = z.object({
  error: z.string(),
  message: z.string().optional(),
  issues: z.array(z.object({ path: z.string(), message: z.string() })).optional(),
});
export type ApiError = z.infer<typeof apiError>;

/** Non-negative number with a sane upper bound (guards against typos like 10000 kg). */
export const amount = (max: number) => z.number().finite().min(0).max(max);
